action.command:
cd /tmp && node -e '
const fs = require("fs");
const s = fs.readFileSync("/opt/node/lib/node_modules/pnpm/dist/pnpm.mjs","utf8");
const lines = s.split("\n");
for (let n=0;n<lines.length;n++){
  const m = lines[n];
  if (/minimumReleaseAge/.test(m) && /(env|default|1440|2880|720|4320|process|config|Number|parse|getMinimum|resolveMin)/i.test(m)){
    console.log(n, ":", m.trim().slice(0,150));
  }
}
' 2>&1 | head -30

